function findIndex(values, target) {
  for (let i = 0; i < values.length; i++) {
    if (values[i] === target) return i;
  }
  return -1;
}
console.log(findIndex([7, 2, 9], 9));
console.log(findIndex([], 9));
console.log(findIndex([5, 5], 5));
console.log(findIndex([2, 4], 3));

