function reverseCopy(values) {
  const result = [...values];
  let left = 0;
  let right = result.length - 1;
  while (left < right) {
    [result[left], result[right]] = [result[right], result[left]];
    left++;
    right--;
  }
  return result;
}
const original = [1, 2, 3, 4];
console.log(reverseCopy(original).join(","));
console.log(original.join(","));
console.log(JSON.stringify(reverseCopy([])));
console.log(reverseCopy([7]).join(","));
